    public void testToString() {
        Phoneme phoneme = new Phoneme("a", LanguageSet.ENGLISH);
        String result = phoneme.toString();
        Assert.assertEquals("a[ENGLISH]", result);
    }

    @Test
    public void testToStringWithMerge() {
        Phoneme phoneme1 = new Phoneme("b", LanguageSet.ENGLISH);
        Phoneme phoneme2 = new Phoneme("c", LanguageSet.SPANISH);
        Phoneme phoneme3 = new Phoneme("d", LanguageSet.ENGLISH, LanguageSet.SPANISH);
        String result1 = phoneme1.toString();
        Assert.assertEquals("b[ENGLISH]", result1);
        String result2 = phoneme2.toString();
        Assert.assertEquals("c[SPANISH]", result2);
        String result3 = phoneme3.toString();
        Assert.assertEquals("d[ENGLISH,SPANISH]", result3);
    }

    @Test
    public void testComparator() {
        Phoneme phoneme1 = new Phoneme("a", LanguageSet.ENGLISH);
        Phoneme phoneme2 = new Phoneme("b", LanguageSet.ENGLISH);
        Phoneme phoneme3 = new Phoneme("c", LanguageSet.SPANISH);
        List<Phoneme> list = new ArrayList<Phoneme>(Arrays.asList(phoneme1, phoneme2, phoneme3));
        Collections.sort(list, Phoneme.COMPARATOR);
        Assert.assertEquals("c[SPANISH]", list.get(0).toString());
        Assert.assertEquals("b[ENGLISH]", list.get(1).toString());
        Assert.assertEquals("a[ENGLISH]", list.get(2).toString());
    }

