    public void testGetLanguages() {
        Phoneme phoneme = new Phoneme("a", LanguageSet.ENGLISH);
        LanguageSet result = phoneme.getLanguages();
        Assert.assertEquals(LanguageSet.ENGLISH, result);
    }
